@misc{kirschner2026offloading,
  author       = {Kirschner, Paul A.},
  title        = {Offloading? No Outsourcing!},
  year         = {2026},
  month        = {1},
  howpublished = {Substack post},
  note         = {认知外包（Cognitive Outsourcing）与认知卸载之别的术语来源。原话：with offloading, you still think, and the artefact supports you; with outsourcing, the system thinks, and you consume the result。非同行评审文献，已有评论者指出其承载了超出引用支撑的论证重量。建议以 Risko \& Gilbert (2016) 的元认知框架作为理论根基，本条仅作术语命名启发}
}

